WITH unpacked AS (SELECT id, created_at, attributes, SIZE(attributes) AS num_attributes, FORALL(items, li -> li.qty <= 5) AS all_small_qty FROM carts WHERE created_at < '2023-12-01') SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, MIN(created_at) AS first_created_at, MAX(num_attributes) AS max_num_attributes, APPROX_PERCENTILE(num_attributes, 0.5) AS num_attributes_p50 FROM unpacked GROUP BY CUBE (DATE_TRUNC('HOUR', created_at)) HAVING max_num_attributes > 0 ORDER BY hour_window DESC;
